import { ADD, DELETE, EDIT } from "../types/productTypes";

const initalState = ''

const productReducer = (state=initalState, action) => {
  switch (action.type) {
    case ADD:
      return action.payload;
    case EDIT:
      return {};
    case DELETE:
      return {};

    default:
      return state;
  }
};

export { productReducer };
